//! Raw bindings to the `rpi-rgb-led-matrix` C library, generated by bindgen in `build.rs`.
//!
//! Everything here is `unsafe` and C-shaped: only the safe abstractions of `wrapper.rs`
//! use it. Private to `matrix`: the rest of the app can never call the C library directly.

// Generated code: C naming conventions, the whole C API, no `SAFETY` comments
#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(dead_code)]
#![allow(clippy::undocumented_unsafe_blocks)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
